	ListDSHSessions(context.Context, *v1.ListDSHSessionsRequest) (*v1.ListDSHSessionsResponse, error)
	// One of them and a page of its conversation
	// (aide.machine.v1.MachineAdminService.ReadDSHSession).
	ReadDSHSession(context.Context, *v1.ReadDSHSessionRequest) (*v11.ReadDSHSessionResponse, error)
	// Taking one over (aide.machine.v1.MachineAdminService.SetDSHTakeover,
