// RegisterPush calls aide.local.v1.LocalService.RegisterPush.
func (c *localServiceClient) RegisterPush(ctx context.Context, req *v1.RegisterPushRequest) (*v1.RegisterPushResponse, error) {
	response, err := c.registerPush.CallUnary(ctx, connect.NewRequest(req))
	if response != nil {
		return response.Msg, err
	}
	return nil, err
}

// LocalServiceHandler is an implementation of the aide.local.v1.LocalService service.
type LocalServiceHandler interface {
	GetStatus(context.Context, *v1.GetStatusRequest) (*v1.GetStatusResponse, error)
	// Watch sends what this device knows of the owner's world (aided's
	// replica, docs/state-sync.md), then each change, until the caller
	// leaves: the screens follow it instead of polling the List calls, which
	// answer from the same replica. A watcher that falls behind is ended
	// (RESOURCE_EXHAUSTED) and should watch again.
	Watch(context.Context, *v1.WatchRequest, *connect.ServerStream[v1.WatchResponse]) error
	// Accounts (docs/trusted-devices.md 4.8): a device keeps a profile for
	// each owner it set up or joined, each with its own root key, and uses one
	// at a time, the current one, which every other call acts on.
	ListProfiles(context.Context, *v1.ListProfilesRequest) (*v1.ListProfilesResponse, error)
	// Makes another profile current: the current one disconnects and its
	// machine stops; the other connects, unless it is signed out.
	SwitchProfile(context.Context, *v1.SwitchProfileRequest) (*v1.SwitchProfileResponse, error)
	// Makes an empty profile current, to set up or join another owner.
	AddProfile(context.Context, *v1.AddProfileRequest) (*v1.AddProfileResponse, error)
	// Signs the current profile out: it disconnects and its machine stops,
	// but it keeps its keys, so signing in again needs no other device.
	SignOut(context.Context, *v1.SignOutRequest) (*v1.SignOutResponse, error)
	// Signs the current profile in again: on a hosted center with a link
	// code from a browser sign-in to the account that owns it.
	SignIn(context.Context, *v1.SignInRequest) (*v1.SignInResponse, error)
	// Onboarding (docs/accounts.md): a new server is set up with the setup
	// code it printed and the account and password it will keep; any other
	// device logs in with the server, the account and the password. Either
	// way the server signs this device in itself: no other device approves,
	// no codes are compared.
	Setup(context.Context, *v1.SetupRequest) (*v1.SetupResponse, error)
	LogIn(context.Context, *v1.LogInRequest) (*v1.LogInResponse, error)
	// The account: its name; changing it or the password needs the current
	// password, and a new password signs out every other device and agent
	// that logged in.
	GetLogin(context.Context, *v1.GetLoginRequest) (*v1.GetLoginResponse, error)
	SetLogin(context.Context, *v1.SetLoginRequest) (*v1.SetLoginResponse, error)
	// The owner's devices.
	ListDevices(context.Context, *v1.ListDevicesRequest) (*v1.ListDevicesResponse, error)
	// Signs another device out: it can no longer connect, and its own machine
	// is removed.
	RemoveDevice(context.Context, *v1.RemoveDeviceRequest) (*v1.RemoveDeviceResponse, error)
	// Forgets the owner on this device, after it was removed, so it can log
	// in again: its own machine keeps its projects.
	Leave(context.Context, *v1.LeaveRequest) (*v1.LeaveResponse, error)
	// Erases Aide on every device of the owner (docs/erase-everything.md):
	// the server signs the order and keeps it. This device keeps
	// running until FinishErase, to show the others acking.
	EraseEverything(context.Context, *v1.EraseEverythingRequest) (*v1.EraseEverythingResponse, error)
	// How an erase stands: each device, machine and agent, and whether it
	// acked. Without an erase id: what erasing everything would reach now.
	EraseStatus(context.Context, *v1.EraseStatusRequest) (*v1.EraseStatusResponse, error)
	// Erases this device too: the app opens on its first run.
	FinishErase(context.Context, *v1.FinishEraseRequest) (*v1.FinishEraseResponse, error)
	// This Mac as an execution machine.
	SetLocalMachine(context.Context, *v1.SetLocalMachineRequest) (*v1.SetLocalMachineResponse, error)
	// Machines.
	ListMachines(context.Context, *v1.ListMachinesRequest) (*v1.ListMachinesResponse, error)
	RenameMachine(context.Context, *v1.RenameMachineRequest) (*v1.RenameMachineResponse, error)
	SetMachinePaused(context.Context, *v1.SetMachinePausedRequest) (*v1.SetMachinePausedResponse, error)
	// What a coding agent's sessions on a machine run with when the client
	// starting one names no model (a setting, no Touch ID).
	SetAgentDefaults(context.Context, *v1.SetAgentDefaultsRequest) (*v1.SetAgentDefaultsResponse, error)
	RemoveMachine(context.Context, *v1.RemoveMachineRequest) (*v1.RemoveMachineResponse, error)
	// Checks this Mac's coding agents again (installed, version, signed in),
	// in the background: they are only checked when something needs them.
	CheckAgents(context.Context, *v1.CheckAgentsRequest) (*v1.CheckAgentsResponse, error)
	// Hides a coding agent a machine lists, or shows it again (SetAgentHidden).
	SetAgentHidden(context.Context, *v1.SetAgentHiddenRequest) (*v1.SetAgentHiddenResponse, error)
	// Pauses a coding agent on a machine, or resumes it (SetAgentPaused).
	SetAgentPaused(context.Context, *v1.SetAgentPausedRequest) (*v1.SetAgentPausedResponse, error)
	// A machine's git repositories under its home folder, for Add a Project.
	ListMachineRepos(context.Context, *v1.ListMachineReposRequest) (*v1.ListMachineReposResponse, error)
	// The folders in one of a machine's folders, for Add a Project.
	ListMachineFolders(context.Context, *v1.ListMachineFoldersRequest) (*v11.ListFoldersResponse, error)
	// One fixed turn of a coding agent on a machine (Test).
	TestMachineAgent(context.Context, *v1.TestMachineAgentRequest) (*v11.TestAgentResponse, error)
	// Signs a coding agent's command line in on a machine, in a browser that
	// opens there (MachineAdminService.StartAgentLogin, 工单 #51).
	StartMachineAgentLogin(context.Context, *v1.StartMachineAgentLoginRequest) (*v11.StartAgentLoginResponse, error)
	// The ops log: the commands agents ran, or were refused, on the
	// machines (docs/machine-ops.md), newest first, as each machine keeps it.
	ListExecLog(context.Context, *v1.ListExecLogRequest) (*v1.ListExecLogResponse, error)
	// This Mac's diagnostics as text, for the person to copy and send when
	// something does not work: versions, health, PATH and each coding agent.
	// Nothing leaves the Mac unless they do.
	GetDiagnostics(context.Context, *v1.GetDiagnosticsRequest) (*v1.GetDiagnosticsResponse, error)
	// Ends the Computer Control session on this computer's own machine, if
	// one is under way (docs/computer-control.md §4.3): the Mac's menu bar
	// names the device in control and offers this.
	StopScreen(context.Context, *v1.StopScreenRequest) (*v1.StopScreenResponse, error)
	// Projects.
	ListProjects(context.Context, *v1.ListProjectsRequest) (*v1.ListProjectsResponse, error)
	AddProject(context.Context, *v1.AddProjectRequest) (*v1.AddProjectResponse, error)
	RemoveProject(context.Context, *v1.RemoveProjectRequest) (*v1.RemoveProjectResponse, error)
	// Names a project as the owner knows it, in place of its id.
	RenameProject(context.Context, *v1.RenameProjectRequest) (*v1.RenameProjectResponse, error)
	// Agents.
	ListClients(context.Context, *v1.ListClientsRequest) (*v1.ListClientsResponse, error)
	UpdateClient(context.Context, *v1.UpdateClientRequest) (*v1.UpdateClientResponse, error)
	// Gives an agent another name: its grant signed again with that alone
	// changed (Touch ID).
	RenameClient(context.Context, *v1.RenameClientRequest) (*v1.RenameClientResponse, error)
	// The kind of agent a client is, as the owner sets it (工单 #52).
	SetClientCategory(context.Context, *v1.SetClientCategoryRequest) (*v1.SetClientCategoryResponse, error)
	RevokeClient(context.Context, *v1.RevokeClientRequest) (*v1.RevokeClientResponse, error)
	// This computer's `aide` CLI, logged in through this device (work order
	// #39, docs/accounts.md §3.1): no account or password asked again.
	// IssueLocalClientGrant is the CLI's own call (`aide auth login
	// --from-app`): it keeps its key, and this device has the server sign
	// and publish an agent grant for that key, as a password login would
	// give. The local socket is this user's alone, and whoever can open it
	// already acts as the owner: it adds no power. The others are the app's
	// row for it: its state, and logging it in or out (out revokes it).
	IssueLocalClientGrant(context.Context, *v1.IssueLocalClientGrantRequest) (*v1.IssueLocalClientGrantResponse, error)
	GetLocalCLI(context.Context, *v1.GetLocalCLIRequest) (*v1.LocalCLI, error)
	LogInLocalCLI(context.Context, *v1.LogInLocalCLIRequest) (*v1.LocalCLI, error)
	LogOutLocalCLI(context.Context, *v1.LogOutLocalCLIRequest) (*v1.LocalCLI, error)
	// Agents' doorbells (docs/agent-names.md §7): the webhook rung when
	// messages wait for an agent or a name under it.
	ListWakes(context.Context, *v1.ListWakesRequest) (*v1.ListWakesResponse, error)
	SetWake(context.Context, *v1.SetWakeRequest) (*v1.SetWakeResponse, error)
	CheckWake(context.Context, *v1.CheckWakeRequest) (*v1.CheckWakeResponse, error)
	ClearWake(context.Context, *v1.ClearWakeRequest) (*v1.ClearWakeResponse, error)
	OpenWakeLink(context.Context, *v1.OpenWakeLinkRequest) (*v1.OpenWakeLinkResponse, error)
	// Contacts (docs/personas.md), kept on the owner's server for all their
	// devices.
	ListPersonas(context.Context, *v1.ListPersonasRequest) (*v1.ListPersonasResponse, error)
	SavePersona(context.Context, *v1.SavePersonaRequest) (*v1.SavePersonaResponse, error)
	// Forgets a contact; its sessions stay.
	DeletePersona(context.Context, *v1.DeletePersonaRequest) (*v1.DeletePersonaResponse, error)
	// TalkToPersona sends a message to a contact: to the session it talks in
	// if that can still take one, else to a new session started with the
	// contact's presets (docs/personas.md §3).
	TalkToPersona(context.Context, *v1.TalkToPersonaRequest) (*v1.TalkToPersonaResponse, error)
	// Sessions (read across all reachable machines over E2E).
	ListSessions(context.Context, *v1.ListSessionsRequest) (*v1.ListSessionsResponse, error)
	// WatchSessions pushes session changes from every reachable machine as
	// they happen (aided keeps one SessionService.WatchSessions stream per
	// online machine while anyone watches). A watcher that falls behind is
	// ended (RESOURCE_EXHAUSTED) and should watch again.
	WatchSessions(context.Context, *v1.WatchSessionsRequest, *connect.ServerStream[v1.WatchSessionsResponse]) error
	StreamSessionEvents(context.Context, *v1.StreamSessionEventsRequest, *connect.ServerStream[v12.SessionEvent]) error
	// A session's events by seq, as aide.session.v1.SessionService.ListEvents.
	ListSessionEvents(context.Context, *v1.ListSessionEventsRequest) (*v1.ListSessionEventsResponse, error)
	// A tool's whole output (aide.session.v1.SessionService.ReadToolOutput).
	ReadToolOutput(context.Context, *v1.ReadToolOutputRequest, *connect.ServerStream[v12.ToolOutputChunk]) error
	// StartSession starts a session on one of the owner's machines as the
	// owner (created_by "owner"): any project or GitHub repository and coding
	// agent there, as aide.session.v1.SessionService.StartSession checks
	// them (docs/technical-design.md §3.4).
	StartSession(context.Context, *v1.StartSessionRequest) (*v1.SessionResponse, error)
	// SendMessage sends a message to a session the owner started; a session
	// an agent started takes messages from that agent only.
	SendMessage(context.Context, *v1.SendMessageRequest) (*v1.SessionResponse, error)
	InterruptSession(context.Context, *v1.InterruptSessionRequest) (*v1.SessionResponse, error)
	ArchiveSession(context.Context, *v1.ArchiveSessionRequest) (*v1.SessionResponse, error)
	UnarchiveSession(context.Context, *v1.UnarchiveSessionRequest) (*v1.SessionResponse, error)
	// DeleteSession and RenameSession: aide.session.v1.SessionService's.
	DeleteSession(context.Context, *v1.DeleteSessionRequest) (*v1.DeleteSessionResponse, error)
	RenameSession(context.Context, *v1.RenameSessionRequest) (*v1.SessionResponse, error)
	// MarkSessionSeen: aide.session.v1.SessionService's, forwarded to the
	// session's machine (docs/session-states.md §7).
	MarkSessionSeen(context.Context, *v12.MarkSessionSeenRequest) (*v1.SessionResponse, error)
	AnswerQuestion(context.Context, *v1.AnswerQuestionRequest) (*v1.AnswerQuestionResponse, error)
	GetDiff(context.Context, *v1.GetDiffRequest) (*v12.GetDiffResponse, error)
	// aide.session.v1.SessionService.GetSessionInsights, as the owner.
	GetSessionInsights(context.Context, *v12.GetSessionInsightsRequest) (*v12.SessionInsights, error)
	// aide.session.v1.SessionService.PushSession, as the owner.
	PushSession(context.Context, *v1.PushSessionRequest) (*v12.PushSessionResponse, error)
	// aide.session.v1.SessionService.RollbackSession, as the owner.
	RollbackSession(context.Context, *v1.RollbackSessionRequest) (*v1.SessionResponse, error)
	// The DeepSeek Harness sessions Aide did not start, on the machines
	// (aide.machine.v1.MachineAdminService.ListDSHSessions), newest
	// activity first. Read only.
	ListDSHSessions(context.Context, *v1.ListDSHSessionsRequest) (*v1.ListDSHSessionsResponse, error)
	// One of them and a page of its conversation
	// (aide.machine.v1.MachineAdminService.ReadDSHSession).
	ReadDSHSession(context.Context, *v1.ReadDSHSessionRequest) (*v11.ReadDSHSessionResponse, error)
	// Taking one over (aide.machine.v1.MachineAdminService.SetDSHTakeover,
	// SendDSHMessage, InterruptDSHSession).
	SetDSHTakeover(context.Context, *v1.SetDSHTakeoverRequest) (*v11.SetDSHTakeoverResponse, error)
	SendDSHMessage(context.Context, *v1.SendDSHMessageRequest) (*v11.SendDSHMessageResponse, error)
	InterruptDSHSession(context.Context, *v1.InterruptDSHSessionRequest) (*v11.InterruptDSHSessionResponse, error)
	PrepareDSHBridge(context.Context, *v1.PrepareDSHBridgeRequest) (*v11.PrepareDSHBridgeResponse, error)
	// Hands installing the bridge plugin to DSH on the machine (工单 #59).
	InstallDSHBridge(context.Context, *v1.InstallDSHBridgeRequest) (*v11.InstallDSHBridgeResponse, error)
	DSHSessionOptions(context.Context, *v1.DSHSessionOptionsRequest) (*v11.DSHSessionOptionsResponse, error)
	// The Claude Code sessions the Claude desktop app lists on the machines
	// (aide.machine.v1.MachineAdminService.ListClaudeSessions), newest
	// activity first; a machine that can't be reached has them as last read,
	// lost.
	ListClaudeSessions(context.Context, *v1.ListClaudeSessionsRequest) (*v1.ListClaudeSessionsResponse, error)
	// One of them and a page of its conversation
	// (aide.machine.v1.MachineAdminService.ReadClaudeSession).
	ReadClaudeSession(context.Context, *v1.ReadClaudeSessionRequest) (*v11.ReadClaudeSessionResponse, error)
	// The messages each machine holds for the owner before they reach a
	// session, over the machines (aide.machine.v1.MachineAdminService.ListHeldMessages).
	ListHeldMessages(context.Context, *v1.ListHeldMessagesRequest) (*v1.ListHeldMessagesResponse, error)
	// Releases one to its session, or discards it.
	ReleaseHeldMessage(context.Context, *v1.ReleaseHeldMessageRequest) (*v11.ReleaseHeldMessageResponse, error)
	// A machine's custom agents (MachineAdminService.ListCustomAgents and
	// the rest); this device's own machine in process.
	ListMachineCustomAgents(context.Context, *v1.ListMachineCustomAgentsRequest) (*v11.ListCustomAgentsResponse, error)
	SaveMachineCustomAgent(context.Context, *v1.SaveMachineCustomAgentRequest) (*v11.SaveCustomAgentResponse, error)
	RemoveMachineCustomAgent(context.Context, *v1.RemoveMachineCustomAgentRequest) (*v11.RemoveCustomAgentResponse, error)
	TestMachineCustomAgent(context.Context, *v1.TestMachineCustomAgentRequest) (*v11.TestCustomAgentResponse, error)
	// QueryWork counts the work done over a range, by hour or day, from what
	// this device holds of every machine's counts: no machine is asked
	// (docs/work-stats.md §7).
	QueryWork(context.Context, *v1.QueryWorkRequest) (*v1.QueryWorkResponse, error)
	// Notifications while the app is not running (the iPhone): this device's
	// push token and notice key, signed with its device key and sent to the
	// relay, which hands them to the owner's machines.
	RegisterPush(context.Context, *v1.RegisterPushRequest) (*v1.RegisterPushResponse, error)
}

